using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ARC.LogVisualizacionArchivos;namespace GraphApi.Services.ARC.LogVisualizacionArchivos{    public class LogVisualizacionArchivosService : ILogVisualizacionArchivosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public LogVisualizacionArchivosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadLogVisualizacionArchivos>> GetLogVisualizacionArchivos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM arc.LogVisualizacionArchivos (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadLogVisualizacionArchivos>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetLogVisualizacionArchivosDynamic(            int? logVisualizacionArchivoID,            int? archivoID,            int? usuarioID,            string? medio,            string? iPOrigen,            string? userAgent,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "LogVisualizacionArchivoID, ArchivoID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM arc.LogVisualizacionArchivos (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (logVisualizacionArchivoID.HasValue)            {                vSql.Append(" AND LogVisualizacionArchivoID = @LogVisualizacionArchivoID");                vParameters.Add("LogVisualizacionArchivoID",logVisualizacionArchivoID);            }            if (!string.IsNullOrWhiteSpace(medio))            {                vSql.Append(" AND Medio LIKE @Medio");                vParameters.Add("Medio",$"%{medio}%");            }            if (!string.IsNullOrWhiteSpace(iPOrigen))            {                vSql.Append(" AND IPOrigen LIKE @IPOrigen");                vParameters.Add("IPOrigen",$"%{iPOrigen}%");            }            if (!string.IsNullOrWhiteSpace(userAgent))            {                vSql.Append(" AND UserAgent LIKE @UserAgent");                vParameters.Add("UserAgent",$"%{userAgent}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadLogVisualizacionArchivos> CreateLogVisualizacionArchivos(clCreateLogVisualizacionArchivos objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO arc.LogVisualizacionArchivos                (ArchivoID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@ArchivoID, @UsuarioID, @Medio, @IPOrigen, @UserAgent, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.ArchivoID,                objInput.UsuarioID,                objInput.Medio,                objInput.IPOrigen,                objInput.UserAgent,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT LogVisualizacionArchivoID, ArchivoID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado                FROM arc.LogVisualizacionArchivos (NOLOCK)                WHERE LogVisualizacionArchivoID = @LogVisualizacionArchivoID;";            var vReadParams = new { LogVisualizacionArchivoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadLogVisualizacionArchivos>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el LogVisualizacionArchivo con ID {vNewId}.");            return vCreated;        }        public async Task<clReadLogVisualizacionArchivos?> UpdateLogVisualizacionArchivos(clUpdateLogVisualizacionArchivos objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("LogVisualizacionArchivoID", objInput.LogVisualizacionArchivoID);            if (objInput.ArchivoID != null)            {                vSets.Add("ArchivoID = @ArchivoID");                vParameters.Add("ArchivoID", objInput.ArchivoID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.Medio is not null)            {                vSets.Add("Medio = @Medio");                vParameters.Add("Medio", objInput.Medio);            }            if (objInput.IPOrigen is not null)            {                vSets.Add("IPOrigen = @IPOrigen");                vParameters.Add("IPOrigen", objInput.IPOrigen);            }            if (objInput.UserAgent is not null)            {                vSets.Add("UserAgent = @UserAgent");                vParameters.Add("UserAgent", objInput.UserAgent);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE arc.LogVisualizacionArchivos                SET {vSetClause}                WHERE LogVisualizacionArchivoID = @LogVisualizacionArchivoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT LogVisualizacionArchivoID, ArchivoID, UsuarioID, Medio, IPOrigen, UserAgent, bEliminado                FROM arc.LogVisualizacionArchivos (NOLOCK)                WHERE LogVisualizacionArchivoID = @LogVisualizacionArchivoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadLogVisualizacionArchivos>(sSelect, new {  objInput.LogVisualizacionArchivoID });        }        public async Task<bool> DeleteLogVisualizacionArchivos(int nLogVisualizacionArchivosID)        {            const string sSql = @"                DELETE FROM arc.LogVisualizacionArchivos                WHERE LogVisualizacionArchivoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nLogVisualizacionArchivosID });            return vAffected > 0;        }    }}